        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = 1 ether;
        vm.assume(address(this).balance >= amount);
        try c.lockInGuess{value: amount}(h) {} catch { return; }
        bool firstSettleReverted;
        try c.settle() {
            firstSettleReverted = false;
        } catch {
            firstSettleReverted = true;
        }
        bool secondSettleReverted;
        try c.settle() {
            secondSettleReverted = false;
        } catch {
            secondSettleReverted = true;
        }
        assertTrue(!firstSettleReverted || !secondSettleReverted);
    }

    function testFuzz_run(bytes32 h, uint256 amount) public {
        _run(h, amount);
    }

    receive() external payable {}
}

